    private string? _maTruongBo;
    private string? _selectedNamHoc;
    private string? _selectedCapHoc;

    private List<KhoiHoc_DTO>  _khoiList    = new();
    private List<LopHoc_DTO>   _allLopList  = new();
    private List<LopHoc_DTO>   _lopFiltered = new();
    private int    _selKhoiId = 0;
    private string _selMaLop  = "";
    private string _selTenLop = "";
    private int    _selLopId  = 0;

    private List<ScnHieuTruongNhanXetDTO> _data = new();

    // Tab
    private int  _activeTab = 1;
    private bool _quillInited = false;

    // Tab 1 modal
    private bool _showModal = false;
    private ScnHieuTruongNhanXetDTO _editItem = new();
    private Dictionary<string, string> _err = new();
    private ScnHieuTruongNhanXetDTO? _delTarget = null;

    // Tab 2 BGH
    private long _bghSelId    = 0;
    private bool _isSavingBgh = false;
    private bool _bghSavedOk  = false;

    private bool _isLoading = false;
    private bool _isSaving  = false;

    private string _toastMsg = "", _toastCss = "", _toastIcon = "";
    private System.Threading.CancellationTokenSource? _toastCts;

    protected override async Task OnInitializedAsync()
    {
        _maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JS);
        _selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        _selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");

        var tk = TruongService.hGetDanhSachKhoi(_maTruongBo ?? "", _selectedCapHoc ?? "1");
        var tl = TruongService.hGetDanhSachLop(_maTruongBo ?? "", _selectedCapHoc ?? "1", _selectedNamHoc ?? "");
        await Task.WhenAll(tk, tl);
        _khoiList   = tk.Result;
        _allLopList = tl.Result;

        if (_khoiList.Any())
        {
            _selKhoiId   = _khoiList[0].MaKhoi;
            _lopFiltered = _allLopList.Where(l => l.MaKhoi == _selKhoiId).ToList();
        }
        else _lopFiltered = _allLopList.ToList();

        if (_lopFiltered.Any())
        {
            _selMaLop  = _lopFiltered[0].MaLopBo;
            _selTenLop = _lopFiltered[0].TenLop;
            _selLopId  = _lopFiltered[0].IdLopBo;
            await LoadData();
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        // Khởi tạo Quill cho Tab 2
        // Set _quillInited = true TRƯỚC await – chặn race condition khi OnAfterRenderAsync bị gọi nhiều lần
        if (_activeTab == 2 && _bghSelId > 0 && !_quillInited)
        {
            _quillInited = true;  // ← đặt ngay ở đây, trước mọi await
            try
            {
                var item = _data.FirstOrDefault(x => x.Id == _bghSelId);
                await JS.InvokeVoidAsync("scnKhcn.init",
                    "htnx-quill-bgh", "htnx_bgh",
                    "Nhập nội dung duyệt của Ban Giám Hiệu...",
                    item?.BghDuyet ?? "");
            }
            catch
            {
                _quillInited = false; // reset nếu lỗi để thử lại
            }
        }
    }

    // ── FILTER ──
    private async Task OnKhoiChanged(ChangeEventArgs e)
    {
        _selKhoiId   = int.TryParse(e.Value?.ToString(), out var v) ? v : 0;
        _lopFiltered = _selKhoiId == 0 ? _allLopList.ToList()
                       : _allLopList.Where(l => l.MaKhoi == _selKhoiId).ToList();
        if (_lopFiltered.Any())
        {
            _selMaLop  = _lopFiltered[0].MaLopBo;
            _selTenLop = _lopFiltered[0].TenLop;
            _selLopId  = _lopFiltered[0].IdLopBo;
        }
        else { _selMaLop = ""; _selTenLop = ""; _selLopId = 0; }
        ResetBgh();
        if (!string.IsNullOrEmpty(_selMaLop)) await LoadData();
    }

    private async Task OnLopChanged(ChangeEventArgs e)
    {
        _selMaLop = e.Value?.ToString() ?? "";
        var lop  = _lopFiltered.FirstOrDefault(l => l.MaLopBo == _selMaLop);
        _selTenLop = lop?.TenLop ?? "";
        _selLopId  = lop?.IdLopBo ?? 0;
        ResetBgh();
        if (!string.IsNullOrEmpty(_selMaLop)) await LoadData();
    }

    private async Task LoadData()
    {
        if (string.IsNullOrEmpty(_selMaLop)) return;
        _isLoading = true; StateHasChanged();
        try
        {
            _data = await TruongService.hGetHieuTruongNhanXet(
                lopId:  _selLopId > 0 ? _selLopId  : (int?)null,
                namHoc: _selectedNamHoc ?? "");
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isLoading = false; StateHasChanged(); }
    }

    // ── TABS ──
    private async Task SwitchTab(int tab)
    {
        if (_activeTab == tab) return;

        // Hủy Quill cũ khi rời tab 2
        if (_activeTab == 2)
        {
            await JS.InvokeVoidAsync("scnKhcn.destroy", "htnx_bgh", "htnx-quill-bgh");
            _quillInited = false;
        }
        _activeTab = tab;
        _bghSavedOk = false;
    }

    // ── BGH ──
    private async Task OnSelectBghRecord(ChangeEventArgs e)
    {
        var newId = long.TryParse(e.Value?.ToString(), out var v) ? v : 0;
        if (newId == _bghSelId) return;

        // Destroy Quill cũ trước khi đổi record
        _quillInited = true; // chặn OnAfterRender khởi tạo trong khi đang cleanup
        try { await JS.InvokeVoidAsync("scnKhcn.destroy", "htnx_bgh", "htnx-quill-bgh"); } catch { }
        _quillInited = false;
        _bghSelId   = newId;
        _bghSavedOk = false;
        StateHasChanged();
    }

    private async Task SaveBgh()
    {
        if (_bghSelId <= 0) return;
        var item = _data.FirstOrDefault(x => x.Id == _bghSelId);
        if (item == null) return;

        var html = await JS.InvokeAsync<string>("scnKhcn.getContent", "htnx_bgh");
        item.BghDuyet = html;

        _isSavingBgh = true; StateHasChanged();
        try
        {
            await TruongService.hUpsertHieuTruongNhanXet(item);
            _bghSavedOk = true;
            await ShowToast("Đã lưu nội dung duyệt BGH!", "toast-ok", "check_circle");
            // Tắt dấu ✓ sau 3s
            _ = Task.Delay(3000).ContinueWith(_ => { _bghSavedOk = false; InvokeAsync(StateHasChanged); });
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isSavingBgh = false; StateHasChanged(); }
    }

    private void ResetBgh()
    {
        _bghSelId   = 0;
        _quillInited = false;
        _bghSavedOk = false;
    }

    // ── MODAL TAB 1 ──
    private void OpenAdd()
    {
        _editItem = new ScnHieuTruongNhanXetDTO
        {
            KhoiId = _selKhoiId > 0 ? _selKhoiId : (int?)null,
            LopId  = _selLopId  > 0 ? _selLopId  : (int?)null,
            NamHoc = _selectedNamHoc ?? "",
            ThoiGianKiemTra = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")
        };
        _err = new(); _showModal = true;
    }

    private void OpenEdit(ScnHieuTruongNhanXetDTO item)
    {
        _editItem = new ScnHieuTruongNhanXetDTO
        {
            Id               = item.Id,
            KhoiId           = item.KhoiId,
            LopId            = item.LopId,
            ThoiGianKiemTra  = item.ThoiGianKiemTra,
            NoiDungKiemTra   = StripHtml(item.NoiDungKiemTra),
            NhaTruongDanhGia = StripHtml(item.NhaTruongDanhGia),
            BghDuyet         = item.BghDuyet,   // BghDuyet giữ nguyên HTML (quill)
            NamHoc           = item.NamHoc
        };
        _err = new(); _showModal = true;
    }

    private void CloseModal() => _showModal = false;

    private void OnThoiGianChanged(ChangeEventArgs e)
    {
        var raw = e.Value?.ToString() ?? "";
        if (string.IsNullOrEmpty(raw)) { _editItem.ThoiGianKiemTra = ""; return; }
        if (DateTime.TryParse(raw, out var dt))
            _editItem.ThoiGianKiemTra = dt.ToString("yyyy-MM-dd HH:mm:ss");
        else
            _editItem.ThoiGianKiemTra = raw.Replace("T", " ");
    }

    private async Task SaveModal()
    {
        _err = new();
        if (string.IsNullOrWhiteSpace(_editItem.ThoiGianKiemTra))
            _err["tg"] = "Vui lòng chọn thời gian kiểm tra";
        if (string.IsNullOrWhiteSpace(_editItem.NoiDungKiemTra))
            _err["nd"] = "Vui lòng nhập nội dung kiểm tra";
        if (string.IsNullOrWhiteSpace(_editItem.NhaTruongDanhGia))
            _err["dg"] = "Vui lòng nhập đánh giá";
        if (_err.Any()) { StateHasChanged(); return; }

        _isSaving = true; StateHasChanged();
        try
        {
            _editItem.KhoiId = _selKhoiId > 0 ? _selKhoiId : (int?)null;
            _editItem.LopId  = _selLopId  > 0 ? _selLopId  : (int?)null;
            _editItem.NamHoc = _selectedNamHoc ?? "";
            await TruongService.hUpsertHieuTruongNhanXet(_editItem);
            await LoadData();
            _showModal = false;
            await ShowToast(_editItem.Id > 0 ? "Đã cập nhật!" : "Đã thêm lần kiểm tra!", "toast-ok", "check_circle");
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isSaving = false; StateHasChanged(); }
    }

    private async Task DoDelete()
    {
        if (_delTarget == null) return;
        _isSaving = true; StateHasChanged();
        try
        {
            await TruongService.hDeleteHieuTruongNhanXet(_delTarget.Id);
            if (_bghSelId == _delTarget.Id) ResetBgh();
            _delTarget = null;
            await LoadData();
            await ShowToast("Đã xoá!", "toast-ok", "check_circle");
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isSaving = false; StateHasChanged(); }
    }

    // ── HELPERS ──
    private static string FormatThoiGian(string? raw)
    {
        if (string.IsNullOrEmpty(raw)) return "";
        return DateTime.TryParse(raw, out var dt) ? dt.ToString("dd/MM/yyyy HH:mm") : raw;
    }

    private static string ToDateTimeLocalValue(string? raw)
    {
        if (string.IsNullOrEmpty(raw)) return "";
        return DateTime.TryParse(raw, out var dt) ? dt.ToString("yyyy-MM-ddTHH:mm:ss") : "";
    }

    private static string StripHtml(string? html)
    {
        if (string.IsNullOrEmpty(html)) return "";
        html = System.Text.RegularExpressions.Regex.Replace(html, @"<br\s*/?>", "\n",
               System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        html = System.Text.RegularExpressions.Regex.Replace(html, @"</p>", "\n",
               System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        html = System.Text.RegularExpressions.Regex.Replace(html, @"<[^>]+>", "");
        html = html.Replace("&nbsp;", " ").Replace("&amp;", "&")
                   .Replace("&lt;", "<").Replace("&gt;", ">")
                   .Replace("&quot;", "\"");
        return html.Trim();
    }

    private static string TruncateText(string? text, int max)
    {
        if (string.IsNullOrEmpty(text)) return "";
        return text.Length <= max ? text : text[..max] + "…";
    }

    private async Task ShowToast(string msg, string css, string icon)
    {
        _toastCts?.Cancel();
        _toastCts = new System.Threading.CancellationTokenSource();
        _toastMsg = msg; _toastCss = css; _toastIcon = icon;
        StateHasChanged();
        try { await Task.Delay(3500, _toastCts.Token); _toastMsg = ""; StateHasChanged(); }
        catch (TaskCanceledException) { }
    }

